/** Serialize to the .zcorpus binary (must equal tests/abi/golden/abi_corpus.zcorpus). */
export function corpusBinary(): Uint8Array {
  let size = 12;
  for (const c of ABI_CORPUS) size += 2 + c.name.length + 4 + c.packet.length + 4;
  const out = new Uint8Array(size);
  const dv = new DataView(out.buffer);
  dv.setUint32(0, 0x524f435a, true); // 'ZCOR'
  dv.setUint16(4, 1, true);
  dv.setUint16(6, 0, true);
  dv.setUint32(8, ABI_CORPUS.length, true);
  let off = 12;
  const enc = new TextEncoder();
  for (const c of ABI_CORPUS) {
    const name = enc.encode(c.name);
    dv.setUint16(off, name.length, true); off += 2;
    out.set(name, off); off += name.length;
    dv.setUint32(off, c.packet.length, true); off += 4;
    out.set(c.packet, off); off += c.packet.length;
    dv.setUint32(off, c.expectedError, true); off += 4;
  }
  return out;
}
